def internal_growth_rate(assets_sales_ratio, liabilities_sales_ratio, net_profit_margin, dividend_payout_ratio):
    # 解方程：0 = assets_sales_ratio - liabilities_sales_ratio - net_profit_margin * ((1 + g) / g) * (1 - dividend_payout_ratio)
    # 这里使用数值方法近似求解
    from scipy.optimize import fsolve
    def equation(g):
        return assets_sales_ratio - liabilities_sales_ratio - net_profit_margin * ((1 + g) / g) * (1 - dividend_payout_ratio)
    return fsolve(equation, 0.1)[0]

