from scipy.stats import norm

def black_scholes_call(asset_price, strike_price, risk_free_rate, volatility, time_to_maturity):
    d1 = (math.log(asset_price / strike_price) + (risk_free_rate + 0.5 * volatility**2) * time_to_maturity) / (volatility * math.sqrt(time_to_maturity))
    d2 = d1 - volatility * math.sqrt(time_to_maturity)
    return asset_price * norm.cdf(d1) - strike_price * math.exp(-risk_free_rate * time_to_maturity) * norm.cdf(d2)

