def calculate_call_option_price(current_stock_price, strike_price, time_to_maturity, risk_free_rate, volatility):
 if time_to_maturity <= 0:
 return max(0, current_stock_price - strike_price)
 d1 = calculate_d1(current_stock_price, strike_price, time_to_maturity, risk_free_rate, volatility)
 d2 = calculate_d2(current_stock_price, strike_price, time_to_maturity, risk_free_rate, volatility)
 call_price = current_stock_price * norm.cdf(d1) - strike_price * math.exp(-risk_free_rate * time_to_maturity) * norm.cdf(d2)
 return call_price

def calculate_put_option_price(current_stock_price, strike_price, time_to_maturity, risk_free_rate, volatility):
 if time_to_maturity <= 0:
 return max(0, strike_price - current_stock_price)
 d1 = calculate_d1(current_stock_price, strike_price, time_to_maturity, risk_free_rate, volatility)
 d2 = calculate_d2(current_stock_price, strike_price, time_to_maturity, risk_free_rate, volatility)
 put_price = strike_price * math.exp(-risk_free_rate * time_to_maturity) * norm.cdf(-d2) - current_stock_price * norm.cdf(-d1)
 return put_price

