def maximum_drawdown(net_asset_value):
    mdd = 0.0
    peak = float('-inf')
    for nav in net_asset_value:
        if nav > peak:
            peak = nav
        drawdown = (peak - nav) / peak
        if drawdown > mdd:
            mdd = drawdown
    return mdd

