    d1 = (math.log(asset_price / strike_price) + (risk_free_rate + volatility**2 / 2) * time_to_expiration) / (volatility * math.sqrt(time_to_expiration))
    return asset_price * norm.pdf(d1) * math.sqrt(time_to_expiration)

def expansion_option_sensitivity_rho(asset_price, strike_price, risk_free_rate, volatility, time_to_expiration):
    import math
    from scipy.stats import norm
    d1 = (math.log(asset_price / strike_price) + (risk_free_rate + volatility**2 / 2) * time_to_expiration) / (volatility * math.sqrt(time_to_expiration))
    d2 = d1 - volatility * math.sqrt(time_to_expiration)
    return strike_price * time_to_expiration * math.exp(-risk_free_rate * time_to_expiration) * norm.cdf(d2)

