def ytm_general(bond_price, coupon_payment, face_value, periods):
    def equation(r):
        pv = sum(coupon_payment / (1 + r) ** t for t in range(1, periods + 1))
        pv += face_value / (1 + r) ** periods
        return bond_price - pv
    low, high = 0, 1
    for _ in range(1000):
        mid = (low + high) / 2
        if equation(mid) > 0:
            low = mid
        else:
            high = mid
    return (low + high) / 2

def ytm_simple(face_value, coupon_rate, years_to_maturity, purchase_price, remaining_years):
