def ytm_annuity(bond_price, coupon_payment, face_value, periods):
    def equation(r):
        annuity_factor = (1 - (1 + r) ** -periods) / r if r != 0 else periods
        pv_annuity = coupon_payment * annuity_factor
        pv_face = face_value * (1 + r) ** -periods
        return bond_price - (pv_annuity + pv_face)
    low, high = 0, 1
    for _ in range(1000):
        mid = (low + high) / 2
        if equation(mid) > 0:
            low = mid
        else:
            high = mid
    return (low + high) / 2

