import math
def standard_normal_pdf(random_variable_value):
    coefficient = 1 / math.sqrt(2 * math.pi)
    exponent = - (random_variable_value ** 2) / 2
    return coefficient * math.exp(exponent)

def standard_normal_cdf_v2(standardized_random_variable_value, n=1000):
    import math
    def simpson_integral(f, a, b, n):
        if n % 2 != 0:
            n += 1
        h = (b - a) / n
        integral = f(a) + f(b)
        for i in range(1, n):
            x = a + i * h
            if i % 2 == 0:
                integral += 2 * f(x)
            else:
                integral += 4 * f(x)
        integral *= h / 3
        return integral
    def pdf(t):
        return (1 / math.sqrt(2 * math.pi)) * math.exp(-t**2 / 2)
    a = -10.0
    b = standardized_random_variable_value
    if b < a:
        a, b = b, a
    integral = simpson_integral(pdf, a, b, n)
    return integral if standardized_random_variable_value >= 0 else 1 - integral

def standard_normal_cumulative_probability_function(x):
