def before_tax_debt_cost_v2(bond_price, coupon_payment, face_value, periods):
    cash_flows = [-bond_price] + [coupon_payment] * (periods - 1) + [coupon_payment + face_value]
    def npv(rate):
        return sum(cf / (1 + rate) ** i for i, cf in enumerate(cash_flows))
    low, high = 0.0, 1.0
    for _ in range(1000):
        mid = (low + high) / 2
        if npv(mid) > 0:
            low = mid
        else:
            high = mid
    return (low + high) / 2

def money_weighted_rate_of_return(cash_flows, initial_guess=0.1, max_iter=100, tol=1e-6):
    rate = initial_guess
    for i in range(max_iter):
        npv = sum(cf / ((1 + rate) ** t) for t, cf in enumerate(cash_flows))
        derivative = sum(-t * cf / ((1 + rate) ** (t + 1)) for t, cf in enumerate(cash_flows) if t > 0)
        if abs(derivative) < 1e-12:
            break
        new_rate = rate - npv / derivative
        if abs(new_rate - rate) < tol:
            return new_rate
        rate = new_rate
    return rate

