def individual_income_tax_payable_v1(wage_income, pension, medical, unemployment, housing_fund, basic_deduction, applicable_tax_rate, quick_deduction):
    taxable_income = wage_income - pension - medical - unemployment - housing_fund - basic_deduction
    return taxable_income * applicable_tax_rate - quick_deduction

def individual_income_tax_payable_v3(comprehensive_income, basic_deduction, special_deductions, special_additional_deductions, other_deductions):
    taxable_income = comprehensive_income - basic_deduction - special_deductions - special_additional_deductions - other_deductions
    tax_brackets = [0.03, 0.1, 0.2, 0.25, 0.3, 0.35, 0.45]
    quick_deductions = [0, 2520, 16920, 31920, 52920, 85920, 181920]
    tax_amounts = [taxable_income * rate - deduction for rate, deduction in zip(tax_brackets, quick_deductions)]
    return max(max(tax_amounts), 0)

def income_tax_payable_v2(total_revenue, non_taxable_revenue, tax_exempt_revenue, total_deductions, prior_year_losses, tax_rate, tax_reduction, tax_credit):
    taxable_income = total_revenue - non_taxable_revenue - tax_exempt_revenue - total_deductions - prior_year_losses
    return taxable_income * tax_rate - tax_reduction - tax_credit

def corporate_growth_rate_v3(current_year_operating_income, previous_year_operating_income):
    income_increment = current_year_operating_income - previous_year_operating_income
    return income_increment / previous_year_operating_income * 100

def low_discount_rate_v2(low_risk_free_rate, low_industry_risk, low_business_risk, low_financial_risk, low_inflation_rate):
    low_risk_premium = low_industry_risk + low_business_risk + low_financial_risk
    return low_risk_free_rate + low_risk_premium + low_inflation_rate

def bond_effective_term_v1(cash_flow_present_values, periods, bond_price):
    numerator = sum([periods[i] * cash_flow_present_values[i] for i in range(len(periods))])
    return numerator / bond_price

def bond_effective_term_v2(cash_flows, periods, yield_to_maturity, bond_price):
    numerator = sum([periods[i] * cash_flows[i] / ((1 + yield_to_maturity) ** periods[i]) for i in range(len(periods))])
    return numerator / bond_price

def allowable_loss_carryforward_v3(taxable_income_current_year, loss_list_chronological):
    remaining_income = taxable_income_current_year
    total_deducted_loss = 0
    for loss in loss_list_chronological:
        if remaining_income <= 0:
            break
        deductible_amount = min(remaining_income, loss)
        total_deducted_loss += deductible_amount
        remaining_income -= deductible_amount
    return total_deducted_loss

def allowable_tax_credit_v2(total_taxable_income_worldwide, applicable_tax_rate, taxable_income_from_foreign_country, total_taxable_income, foreign_tax_paid):
    credit_limit = total_taxable_income_worldwide * applicable_tax_rate * (taxable_income_from_foreign_country / total_taxable_income)
    return min(credit_limit, foreign_tax_paid)

def pension_obligation_v1(future_payments, payment_probabilities, discount_rate, periods):
    total_pv = 0
    for i in range(len(future_payments)):
        pv = (future_payments[i] * payment_probabilities[i]) / ((1 + discount_rate) ** periods[i])
        total_pv += pv
    return total_pv

def npv_absolute_v3(net_cash_flows, discount_rate, initial_investment):
    total_pv = sum(cf / ((1 + discount_rate) ** (i + 1)) for i, cf in enumerate(net_cash_flows))
    return total_pv - initial_investment

def impairment_provision_v2(book_value, fair_value, disposal_costs):
    recoverable_amount = fair_value - disposal_costs
    return max(0, book_value - recoverable_amount)

def impairment_provision_v3(book_value, present_value_of_future_cash_flows):
    recoverable_amount = present_value_of_future_cash_flows
    return max(0, book_value - recoverable_amount)

def weighted_average_cost_of_capital_v2(capital_sources):
    total_weighted_cost = 0
    for source in capital_sources:
        total_weighted_cost += source['cost'] * source['weight']
    return total_weighted_cost

def market_value_income_approach(expected_cash_flows, discount_rate):
    total_value = 0
    for period, cash_flow in enumerate(expected_cash_flows, start=1):
        total_value += cash_flow / ((1 + discount_rate) ** period)
    return total_value

def unit_direct_material_cost_v1(raw_material_cost, auxiliary_material_cost, spare_parts_cost, purchased_semi_finished_goods_cost, packaging_cost, low_value_consumables_cost, product_quantity):
    total_material_cost = raw_material_cost + auxiliary_material_cost + spare_parts_cost + purchased_semi_finished_goods_cost + packaging_cost + low_value_consumables_cost
    return total_material_cost / product_quantity

def unit_direct_material_cost_v2(material_price_standards, material_quantity_standards):
    if len(material_price_standards) != len(material_quantity_standards):
        raise ValueError("材料价格标准列表与材料用量标准列表长度必须一致")
    total_standard_cost = sum(price * quantity for price, quantity in zip(material_price_standards, material_quantity_standards))
    return total_standard_cost

def historical_average_price_v2(price_list):
    total_price = 0
    for price in price_list:
        total_price += price
    return total_price / len(price_list)

def historical_price_std_dev(prices):
    import math
    mean_price = sum(prices) / len(prices)
    sum_squared_diff = sum((price - mean_price) ** 2 for price in prices)
    variance = sum_squared_diff / (len(prices) - 1)
    return math.sqrt(variance)

def sample_variance_of_historical_returns(historical_returns):
    n = len(historical_returns)
    mean_return = sum(historical_returns) / n
    sum_of_squared_deviations = sum((r - mean_return) ** 2 for r in historical_returns)
    return sum_of_squared_deviations / (n - 1)

def present_value_of_initial_investment_v1(investment_amounts, discount_rate):
    total_pv = 0
    for t, amount in enumerate(investment_amounts, start=1):
        total_pv += amount / ((1 + discount_rate) ** t)
    return total_pv

def prior_period_data_v1(query_function, financial_metric, current_period):
    prior_period = current_period - 1
    return query_function(financial_metric, prior_period)

def avg_ps_v2(market_caps, revenues):
    ps_ratios = [mc / rev for mc, rev in zip(market_caps, revenues)]
    return sum(ps_ratios) / len(ps_ratios)

def avg_ps_v3(stock_prices, sales_per_shares):
    ps_ratios = [sp / sps for sp, sps in zip(stock_prices, sales_per_shares)]
    return sum(ps_ratios) / len(ps_ratios)

def product_sales_mix_ratio_v2(product_quantity, product_unit_price, total_sales):
    product_sales = product_quantity * product_unit_price
    return (product_sales / total_sales) * 100

def income_tax_expense_v3(accounting_profit, permanent_differences, tax_rate):
    taxable_income = accounting_profit + permanent_differences
    return taxable_income * tax_rate

def probability_of_state_v2(successes, trials, success_probability):
    from math import comb
    return comb(trials, successes) * (success_probability ** successes) * ((1 - success_probability) ** (trials - successes))

def recovery_amount_v2(initial_investment, interest_rate, number_of_periods):
    capital_recovery_factor = interest_rate / (1 - (1 + interest_rate) ** (-number_of_periods))
    return initial_investment * capital_recovery_factor

def recovery_amount_v3(initial_investment, interest_rate, number_of_periods):
    annuity_present_value_factor = (1 - (1 + interest_rate) ** (-number_of_periods)) / interest_rate
    return initial_investment / annuity_present_value_factor

def ending_balance_allowance_v2(opening_balance_receivable, increase_receivable, decrease_receivable, bad_debt_provision_rate):
    ending_balance_receivable = opening_balance_receivable + increase_receivable - decrease_receivable
    return ending_balance_receivable * bad_debt_provision_rate

def base_period_iit_v2(base_period_income, tax_threshold, special_deductions, special_additional_deductions, other_deductions, applicable_tax_rate, quick_deduction):
    taxable_income = base_period_income - tax_threshold - special_deductions - special_additional_deductions - other_deductions
    return taxable_income * applicable_tax_rate - quick_deduction

def base_period_income_tax_payable_v2(total_revenue, non_taxable_revenue, tax_exempt_revenue, total_deductions, prior_year_losses_carried_forward, applicable_tax_rate):
    taxable_income = total_revenue - non_taxable_revenue - tax_exempt_revenue - total_deductions - prior_year_losses_carried_forward
    return taxable_income * applicable_tax_rate

def market_portfolio_expected_return_v2(weights_list, expected_returns_list):
    if len(weights_list) != len(expected_returns_list):
        raise ValueError("权重列表与预期收益率列表长度必须一致")
    return sum(w * r for w, r in zip(weights_list, expected_returns_list))

def market_return_variance_v1(return_list, probability_list, expected_return):
    variance = 0
    for i in range(len(return_list)):
        variance += (return_list[i] - expected_return) ** 2 * probability_list[i]
    return variance

def market_portfolio_variance_v1(weights, covariance_matrix):
    import numpy as np
    weights = np.array(weights)
    cov_matrix = np.array(covariance_matrix)
    return np.dot(weights.T, np.dot(cov_matrix, weights))

def market_std_dev_v1(historical_returns):
    import math
    mean_return = sum(historical_returns) / len(historical_returns)
    sum_sq_diff = sum((r - mean_return) ** 2 for r in historical_returns)
    return math.sqrt(sum_sq_diff / (len(historical_returns) - 1))

def market_std_dev_v2(possible_returns, probabilities):
    import math
    expected_return = sum(p * r for p, r in zip(probabilities, possible_returns))
    variance = sum(p * (r - expected_return) ** 2 for p, r in zip(probabilities, possible_returns))
    return math.sqrt(variance)

def net_increase_output_vat_v2(current_sales, applicable_tax_rate, deductible_input_vat, input_vat_transferred_out):
    current_output_vat = current_sales * applicable_tax_rate
    return current_output_vat - (deductible_input_vat - input_vat_transferred_out)

def net_increase_output_vat_v3(current_tax_inclusive_sales, applicable_tax_rate, actual_deducted_input_vat):
    current_output_vat = (current_tax_inclusive_sales / (1 + applicable_tax_rate)) * applicable_tax_rate
    return current_output_vat - actual_deducted_input_vat

def income_tax_payable_v2(pre_tax_accounting_profit, tax_adjustment_increase, tax_adjustment_decrease, tax_rate):
    taxable_income = pre_tax_accounting_profit + tax_adjustment_increase - tax_adjustment_decrease
    return taxable_income * tax_rate

def income_tax_payable_v3(total_revenue, non_taxable_revenue, tax_exempt_revenue, total_deductions, prior_year_losses_carried_forward, tax_rate):
    taxable_income = total_revenue - non_taxable_revenue - tax_exempt_revenue - total_deductions - prior_year_losses_carried_forward
    return taxable_income * tax_rate

def gross_output_of_construction(budget_unit_price_list, actual_quantity_list, indirect_expense_rate, planned_profit_rate, tax_rate):
    total = 0
    for price, quantity in zip(budget_unit_price_list, actual_quantity_list):
        total += price * quantity * (1 + indirect_expense_rate)
    return total * (1 + planned_profit_rate) * (1 + tax_rate)

def construction_period_interest_v1(annual_beginning_balance, annual_borrowing, annual_interest_rate):
    total_interest = 0
    for i in range(len(annual_beginning_balance)):
        interest = (annual_beginning_balance[i] + annual_borrowing[i] / 2) * annual_interest_rate[i]
        total_interest += interest
    return total_interest

def current_income_tax_v2(pre_tax_accounting_profit, tax_adjustment_increase, tax_adjustment_decrease, tax_rate):
    taxable_income = pre_tax_accounting_profit + tax_adjustment_increase - tax_adjustment_decrease
    return taxable_income * tax_rate

def total_amount_to_be_allocated_v5(total_service_volume, amount_to_allocate, other_service_consumption):
    allocation_rate = amount_to_allocate / (total_service_volume - other_service_consumption)
    return total_service_volume * allocation_rate

def population_standard_deviation(data_points):
    import math
    n = len(data_points)
    mean = sum(data_points) / n
    variance = sum((x - mean) ** 2 for x in data_points) / n
    return math.sqrt(variance)

def total_tax_payable_v3(output_vat, input_vat, consumption_tax_payable, corporate_income_tax_payable, other_taxes_payable):
    vat_payable = output_vat - input_vat
    return vat_payable + consumption_tax_payable + corporate_income_tax_payable + other_taxes_payable

def nopat_v2(operating_revenue, operating_cost, operating_expense, effective_tax_rate):
    ebit = operating_revenue - operating_cost - operating_expense
    return ebit * (1 - effective_tax_rate)

def investment_period_v3(annual_rate, payment_per_period, present_value):
    import math
    rate = annual_rate
    pmt = payment_per_period
    pv = present_value
    if rate == 0 or pmt <= pv * rate:
        return None
    return -math.log(1 - pv * rate / pmt) / math.log(1 + rate)

def investment_period_v4(annual_rate, present_value, future_value):
    import math
    rate = annual_rate
    pv = present_value
    fv = future_value
    if pv <= 0 or fv <= 0 or rate <= -1:
        return None
    return math.log(fv / pv) / math.log(1 + rate)

def portfolio_std_dev_v1(weights, std_devs, corr_matrix):
    import numpy as np
    cov_matrix = np.outer(std_devs, std_devs) * corr_matrix
    portfolio_variance = np.dot(weights.T, np.dot(cov_matrix, weights))
    return np.sqrt(portfolio_variance)

def portfolio_std_dev_v2(weight_a, weight_b, std_dev_a, std_dev_b, corr_ab):
    import math
    portfolio_variance = (weight_a**2 * std_dev_a**2) + (weight_b**2 * std_dev_b**2) + (2 * weight_a * weight_b * std_dev_a * std_dev_b * corr_ab)
    return math.sqrt(portfolio_variance)

def sampling_error_margin_v1(population_variance, sample_size, z_score):
    import math
    return math.sqrt(population_variance / sample_size) * z_score

def sampling_error_margin_v2(sample_size, z_score):
    import math
    return math.sqrt(2500 / sample_size) * z_score

def surplus_reserve_v2(net_profit_current_year, beginning_retained_earnings, beginning_uncovered_loss, appropriation_ratio):
    distributable_profit = net_profit_current_year + beginning_retained_earnings - beginning_uncovered_loss
    return distributable_profit * appropriation_ratio

def slope_v3(angle_radians):
    import math
    return math.tan(angle_radians)

def minimum_average_total_cost(total_costs, quantities):
    average_total_costs = [tc / q for tc, q in zip(total_costs, quantities)]
    return min(average_total_costs)

def option_price_change_v1(up_probability, up_option_value, down_probability, down_option_value, risk_free_rate, current_option_price):
    expected_value = (up_probability * up_option_value + down_probability * down_option_value) / (1 + risk_free_rate)
    return expected_value - current_option_price

def holding_period_return_v2(period_returns):
    import math
    product = 1
    for r in period_returns:
        product *= (1 + r)
    return product - 1

def holding_period_return_v3(expected_cash_flows, discount_rate):
    pv = 0
    for t, cf in enumerate(expected_cash_flows, start=1):
        pv += cf / ((1 + discount_rate) ** t)
    return pv

def number_of_periods_v1(ending_value, beginning_value, historical_growth_rate):
    import math
    return math.log(ending_value / beginning_value) / math.log(1 + historical_growth_rate)

def number_of_periods_v2(ending_value, beginning_value, period_expense_ratio):
    import math
    return math.log(ending_value / beginning_value) / math.log(1 + period_expense_ratio)

def present_value_of_future_cash_flows_v1(cash_flows, discount_rate):
    total_pv = 0
    for t, cf in enumerate(cash_flows, start=1):
        total_pv += cf / ((1 + discount_rate) ** t)
    return total_pv

def present_value_of_future_cash_flows_v2(cash_flows, risk_adjustment_coefficient, risk_free_rates):
    total_pv = 0
    for t, cf in enumerate(cash_flows, start=1):
        total_pv += (cf * (1 - risk_adjustment_coefficient)) / ((1 + risk_free_rates[t-1]) ** t)
    return total_pv

def future_cash_flows_pv(estimated_cash_flows_list, discount_rate):
    present_value = 0
    for t, cash_flow in enumerate(estimated_cash_flows_list, start=1):
        present_value += cash_flow / ((1 + discount_rate) ** t)
    return present_value

def equity_mva_v3(net_profit, cost_of_equity, equity_capital):
    equity_market_value = net_profit / cost_of_equity
    return equity_market_value - equity_capital

def pv_of_fcfe_v1(fcfe_list, cost_of_equity):
    total_pv = 0
    for t, fcfe in enumerate(fcfe_list, start=1):
        total_pv += fcfe / ((1 + cost_of_equity) ** t)
    return total_pv

def pv_of_fcfe_v2(net_income_list, depreciation_amortization_list, capex_list, change_in_wc_list, net_debt_issued_list, cost_of_equity):
    total_pv = 0
    for t in range(len(net_income_list)):
        fcfe = net_income_list[t] + depreciation_amortization_list[t] - capex_list[t] - change_in_wc_list[t] + net_debt_issued_list[t]
        total_pv += fcfe / ((1 + cost_of_equity) ** (t+1))
    return total_pv

def pv_of_fcfe_v3(ebit_list, tax_rate, depreciation_amortization_list, capex_list, change_in_wc_list, net_debt_issued_list, cost_of_equity):
    total_pv = 0
    for t in range(len(ebit_list)):
        fcfe = ebit_list[t] * (1 - tax_rate) + depreciation_amortization_list[t] - capex_list[t] - change_in_wc_list[t] + net_debt_issued_list[t]
        total_pv += fcfe / ((1 + cost_of_equity) ** (t+1))
    return total_pv

def standard_total_procurement_cost_v2(standard_unit_price_list, standard_purchase_quantity_list):
    total_cost = 0
    for price, quantity in zip(standard_unit_price_list, standard_purchase_quantity_list):
        total_cost += price * quantity
    return total_cost

def standard_total_purchase_quantity_v2(unit_consumption, estimated_production_volume, estimated_ending_inventory, beginning_inventory):
    estimated_material_requirement = unit_consumption * estimated_production_volume
    return estimated_material_requirement + estimated_ending_inventory - beginning_inventory

def equity_value_v2(future_fcfe_list, cost_of_equity):
    total_value = 0
    for period, fcfe in enumerate(future_fcfe_list, start=1):
        total_value += fcfe / ((1 + cost_of_equity) ** period)
    return total_value

def equity_value_v3(comparable_ev, comparable_debt_ratio, target_net_income, comparable_net_income):
    comparable_equity_value = comparable_ev * (1 - comparable_debt_ratio)
    return comparable_equity_value * (target_net_income / comparable_net_income)

def equity_value_v4(total_net_assets, total_shares, target_shares):
    value_per_share = total_net_assets / total_shares
    return value_per_share * target_shares

def downside_asset_price_v3(current_price, downside_return, time):
    import math
    return current_price * math.exp(downside_return * time)

def pmt_from_pv(annuity_present_value, annual_interest_rate, number_of_periods):
    numerator = annual_interest_rate * ((1 + annual_interest_rate) ** number_of_periods)
    denominator = ((1 + annual_interest_rate) ** number_of_periods) - 1
    return annuity_present_value * (numerator / denominator)

def pmt_from_fv(annuity_future_value, annual_interest_rate, number_of_periods):
    numerator = annual_interest_rate
    denominator = ((1 + annual_interest_rate) ** number_of_periods) - 1
    return annuity_future_value * (numerator / denominator)

def periodic_payment_amount_v2(loan_principal, monthly_interest_rate, number_of_periods):
    annuity_factor = (monthly_interest_rate * ((1 + monthly_interest_rate) ** number_of_periods)) / (((1 + monthly_interest_rate) ** number_of_periods) - 1)
    return loan_principal * annuity_factor

def liquidity_adjusted_equity_value_v2(net_profit, cost_of_equity, liquidity_discount_rate):
    equity_market_value = net_profit / cost_of_equity
    return equity_market_value * (1 - liquidity_discount_rate)

def present_value(cash_flows, discount_rate):
