    return np.std(log_return_series) * np.sqrt(annualization_factor)

def stock_price_volatility_v2(log_return_series, annualization_factor):
    import numpy as np
    return np.sqrt(np.var(log_return_series) * annualization_factor)

def equity_volatility_v1(returns):
