def stock_market_return_std_dev_v2(possible_returns, probabilities):
    import math
    expected_return = sum(p * r for r, p in zip(possible_returns, probabilities))
    variance = sum(p * (r - expected_return) ** 2 for r, p in zip(possible_returns, probabilities))
