import math
def natural_logarithm(input_value):
    return math.log(input_value)

def planned_total_profit_v2(planned_operating_revenue, planned_operating_cost, planned_taxes_and_surcharges, planned_period_expenses, planned_asset_impairment_loss, planned_fair_value_change_gains, planned_net_investment_income, planned_non_operating_income, planned_non_operating_expenses):
    planned_operating_profit = planned_operating_revenue - planned_operating_cost - planned_taxes_and_surcharges - planned_period_expenses - planned_asset_impairment_loss + planned_fair_value_change_gains + planned_net_investment_income
    return planned_operating_profit + planned_non_operating_income - planned_non_operating_expenses

def variance_of_returns_v1(returns):
    mean_return = sum(returns) / len(returns)
    squared_deviations = [(r - mean_return) ** 2 for r in returns]
    return sum(squared_deviations) / (len(returns) - 1)

def variance_of_returns_v2(returns):
    mean_return = sum(returns) / len(returns)
    squared_deviations = [(r - mean_return) ** 2 for r in returns]
    return sum(squared_deviations) / len(returns)

def bayes_theorem_v2(likelihoods, prior_probabilities):
    marginal_probability = sum([likelihoods[i] * prior_probabilities[i] for i in range(len(likelihoods))])
    return (likelihoods[0] * prior_probabilities[0]) / marginal_probability

def standard_deviation_of_asset_a_returns(returns_list):
    import math
    n = len(returns_list)
