    else:
        if type == 1:
            pmt_adjusted = pmt * (1 + rate)
        else:
            pmt_adjusted = pmt
        numerator = fv - pmt_adjusted / rate
        denominator = pv + pmt_adjusted / rate
        return math.log(numerator / denominator) / math.log(1 + rate)

