def simpsons_rule_v1(integrand_func, lower_limit, upper_limit):
    midpoint = (lower_limit + upper_limit) / 2
    return (upper_limit - lower_limit) / 6 * (integrand_func(lower_limit) + 4 * integrand_func(midpoint) + integrand_func(upper_limit))

def simpsons_rule_v2(integrand_func, lower_limit, upper_limit, n_subintervals):
    if n_subintervals % 2 != 0:
        n_subintervals += 1
    h = (upper_limit - lower_limit) / n_subintervals
    x = [lower_limit + i * h for i in range(n_subintervals + 1)]
    y = [integrand_func(xi) for xi in x]
    sum_odd = sum(y[i] for i in range(1, n_subintervals, 2))
    sum_even = sum(y[i] for i in range(2, n_subintervals, 2))
    return h / 3 * (y[0] + y[-1] + 4 * sum_odd + 2 * sum_even)

