def cumulative_standard_normal_distribution_function_v1(x):
    import math
    def integrand(t):
        return (1 / math.sqrt(2 * math.pi)) * math.exp(-t**2 / 2)
    def simpson_integral(a, b, n=1000):
        h = (b - a) / n
        s = integrand(a) + integrand(b)
        for i in range(1, n):
            coeff = 4 if i % 2 != 0 else 2
            s += coeff * integrand(a + i * h)
        return s * h / 3
    return simpson_integral(-10, x)

def cumulative_standard_normal_distribution_function_v2(x):
    import math
    if x >= 0:
        t = 1 / (1 + 0.33267 * x)
        pdf = (1 / math.sqrt(2 * math.pi)) * math.exp(-x**2 / 2)
        approximation = pdf * (0.4361836 * t - 0.1201676 * t**2 + 0.9372980 * t**3)
        return 1 - approximation
    else:
        return 1 - cumulative_standard_normal_distribution_function_v2(-x)

