        for demand, prob in demand_distribution.items():
            if demand > lead_time_demand_mean + B:
                expected_shortage += (demand - lead_time_demand_mean - B) * prob
        total_cost = unit_shortage_cost * expected_shortage * annual_order_freq + B * unit_holding_cost
