    import math
    return math.sqrt((2 * total_cash_requirement * conversion_cost) / interest_rate)

def lease_implicit_rate(min_lease_receipts_pv, unguaranteed_residual_pv, fair_value, initial_direct_costs):
    from scipy.optimize import fsolve
    import numpy as np
    def equation(r):
        return min_lease_receipts_pv(r) + unguaranteed_residual_pv(r) - (fair_value + initial_direct_costs)
    initial_guess = 0.05
    result = fsolve(equation, initial_guess)[0]
    return result

def present_value_of_rental_inflows_v1(periodic_rents, discount_rate):
    total_pv = 0
    for i, rent in enumerate(periodic_rents, start=1):
        total_pv += rent / ((1 + discount_rate) ** i)
    return total_pv

def standard_deviation_of_security_j_v1(returns_j, is_population=True):
    import math
    mean = sum(returns_j) / len(returns_j)
    variance = sum((r - mean) ** 2 for r in returns_j) / (len(returns_j) if is_population else (len(returns_j) - 1))
    return math.sqrt(variance)

def standard_deviation_of_security_j_v2(returns_j):
    import statistics
    return statistics.stdev(returns_j)

def expected_return_of_security_j_v3(future_cash_flows, probabilities_of_cash_flows, current_market_price):
    expected_cash_flow = sum(cf * p for cf, p in zip(future_cash_flows, probabilities_of_cash_flows))
    return expected_cash_flow / current_market_price

def outcome_value_v2(cash_flows_per_period, discount_rate):
    total_value = 0
    for t, cf in enumerate(cash_flows_per_period, start=1):
        total_value += cf / ((1 + discount_rate) ** t)
    return total_value

def actual_activity_cost_v3(resource_consumption_list, resource_price_or_rate_list):
    total_cost = 0
    for consumption, price in zip(resource_consumption_list, resource_price_or_rate_list):
        total_cost += consumption * price
    return total_cost

def continuously_compounded_return(ending_price, dividend, beginning_price):
    import math
    return math.log((ending_price + dividend) / beginning_price)

def demand_standard_deviation(demand_series):
    import math
    n = len(demand_series)
    if n < 2:
        return 0.0
    mean_demand = sum(demand_series) / n
    sum_of_squares = sum((x - mean_demand) ** 2 for x in demand_series)
    return math.sqrt(sum_of_squares / (n - 1))

def calculate_year_end_bonus(salary: float, bonus_percentage: float) -> float:
    if salary < 0:
        raise ValueError("Salary must be non-negative.")
    if not (0 <= bonus_percentage <= 100):
        raise ValueError("Bonus percentage must be between 0 and 100.")
    bonus_amount = salary * (bonus_percentage / 100)
    return bonus_amount

def calculate_annual_return(beginning_value: float, ending_value: float, holding_period_years: float) -> float:
    annual_return = ((ending_value / beginning_value) ** (1 / holding_period_years)) - 1
    return annual_return

def schedule_yearly_reinsurance_premiums(net_amounts_at_risk: list, age: int, base_rate: float) -> list:
    premiums = [(nar * base_rate) * (1 + age / 100) for nar in net_amounts_at_risk]
    return premiums

def calculate_annuity_payout(principal: float, interest_rate: float, periods: int) -> float:
    if interest_rate == 0:
        payout = principal / periods
    else:
        payout = principal * (interest_rate * (1 + interest_rate) ** periods) / ((1 + interest_rate) ** periods - 1)
    return payout

def calculate_yield_spread(short_term_yield: float, long_term_yield: float) -> float:
    yield_spread = (long_term_yield - short_term_yield) * 100
    return yield_spread

def calculate_yield_pickup(current_yield: float, new_yield: float) -> float:
    yield_pickup = new_yield - current_yield
    return yield_pickup

def evaluate_yield_swap(coupon_current: float, coupon_new: float, market_conditions_change: float) -> float:
    net_impact = (coupon_new - coupon_current) - market_conditions_change
    return net_impact

def calculate_yield_spread(yield1: float, yield2: float, basis_points: bool = False) -> float:
    spread = yield1 - yield2
    if basis_points:
        spread *= 100
    return spread

def calculate_call_option_intrinsic_value(market_price: float, strike_price: float) -> float:
    intrinsic_value = max(0, market_price - strike_price)
    return intrinsic_value

def determine_call_option_status(market_price: float, strike_price: float) -> str:
    if market_price > strike_price:
        return "in-the-money"
    elif market_price == strike_price:
        return "at-the-money"
    else:
        return "out-of-the-money"

def calculate_roce(ebit: float, capital_employed: float) -> float:
    if capital_employed == 0:
        raise ValueError("Capital employed must be greater than zero.")
    return ebit / capital_employed

def calculate_capitalized_interest(principal: float, interest_rate: float, period_days: int, year_days: int = 365) -> float:
    interest_for_period = principal * interest_rate * (period_days / year_days)
    return interest_for_period

def compute_straight_line_depreciation(asset_cost: float, asset_lifetime: int) -> float:
    annual_depreciation = asset_cost / asset_lifetime
    return annual_depreciation

def calculate_quick_ratio(cash_equivalents: float, marketable_securities: float, accounts_receivable: float, current_liabilities: float) -> float:
    if current_liabilities == 0:
        raise ValueError("Current liabilities must be greater than zero.")
    quick_ratio = (cash_equivalents + marketable_securities + accounts_receivable) / current_liabilities
    return quick_ratio

def calculate_cash_on_cash_return(annual_pre_tax_cash_flow: float, total_cash_invested: float) -> float:
    cash_on_cash_return = (annual_pre_tax_cash_flow / total_cash_invested) * 100
    return cash_on_cash_return

def calculate_annual_pre_tax_cash_flow(gross_scheduled_rent: float, other_income: float, vacancy: float, operating_expenses: float, annual_mortgage_payments: float) -> float:
    annual_pre_tax_cash_flow = (gross_scheduled_rent + other_income - vacancy - operating_expenses - annual_mortgage_payments)
    return annual_pre_tax_cash_flow

def calculate_cheapest_to_deliver(current_bond_price: float, settlement_price: float, conversion_factor: float) -> float:
    ctd = current_bond_price - (settlement_price * conversion_factor)
    return ctd

def calculate_gdp(consumption: float, government_spending: float, investment: float, exports: float, imports: float) -> float:
    gdp = consumption + government_spending + investment + (exports - imports)
    return gdp

def calculate_flow_balance(injections: float, leakages: float) -> bool:
    is_balanced = injections == leakages
    return is_balanced

def calculate_maximum_profit(call_strike: float, stock_purchase_price: float, net_premium: float, net_credit: bool = True) -> float:
    if net_credit:
        max_profit = call_strike - stock_purchase_price + net_premium
    else:
        max_profit = call_strike - stock_purchase_price - net_premium
    return max_profit

def calculate_combined_ratio(incurred_losses: float, expenses: float, earned_premium: float) -> float:
    if earned_premium <= 0:
        raise ValueError("Earned premium must be greater than zero.")
    combined_ratio = (incurred_losses + expenses) / earned_premium * 100
    return combined_ratio

def calculate_trade_basis_combined_ratio(incurred_losses: float, loss_adjustment_expenses: float, underwriting_expenses: float, earned_premium: float, net_written_premium: float) -> float:
    if earned_premium <= 0 or net_written_premium <= 0:
        raise ValueError("Earned premium and net written premium must be greater than zero.")
    trade_basis_combined_ratio = ((incurred_losses + loss_adjustment_expenses) / earned_premium + underwriting_expenses / net_written_premium) * 100
    return trade_basis_combined_ratio

def calculate_hedging_gains_or_losses(locked_in_price: float, market_price: float, quantity: int) -> float:
    gain_or_loss = (locked_in_price - market_price) * quantity
    return gain_or_loss

def calculate_common_size_income_statement(line_items: dict, total_revenue: float) -> dict:
    if total_revenue <= 0:
        raise ValueError("Total revenue must be positive.")
    common_size_percentages = {item: (amount / total_revenue) * 100 for item, amount in line_items.items()}
    return common_size_percentages

def compare_to_peer_average(company_multiple: float, peer_average: float) -> str:
    if company_multiple > peer_average:
        return "overvalued"
    elif company_multiple < peer_average:
        return "undervalued"
    else:
        return "fairly valued"

def calculate_adjusted_price(sold_price: float, adjustments: dict) -> float:
    adjusted_price = sold_price + sum(adjustments.values())
    return adjusted_price

def calculate_future_value(principal: float, annual_rate: float, compounding_periods: int, time_years: float) -> float:
    future_value = principal * (1 + annual_rate / compounding_periods) ** (compounding_periods * time_years)
    return future_value

def calculate_fair_market_value(revenue: float, price_to_revenue_multiple: float) -> float:
    fair_market_value = revenue * price_to_revenue_multiple
    return fair_market_value

def calculate_arbitrage_profit(spot_price: float, futures_price: float, transaction_cost: float) -> float:
    if futures_price <= spot_price:
        raise ValueError("Futures price must be greater than spot price for arbitrage to be possible.")
    arbitrage_profit = (futures_price - spot_price) - transaction_cost
    return arbitrage_profit

def calculate_contra_value(original_value: float, contra_percentage: float) -> float:
    if original_value < 0:
        raise ValueError("Original value must be non-negative.")
    if not (0 <= contra_percentage <= 1):
        raise ValueError("Contra percentage must be between 0 and 1.")
    contra_value = original_value * contra_percentage
    return contra_value

def calculate_bond_duration(price_change: float, interest_rate_change: float) -> float:
    if interest_rate_change == 0:
        raise ValueError("Interest rate change must be non-zero.")
    duration = price_change / interest_rate_change
    return duration

def calculate_convexity(price_change_duration: float, convexity_adjustment: float) -> float:
    adjusted_price_change = price_change_duration + (0.5 * convexity_adjustment)
    return adjusted_price_change

def calculate_variance(standard_cost: float, actual_cost: float) -> float:
    variance = actual_cost - standard_cost
    return variance

def calculate_capital_gain(sale_price: float, cost_basis: float) -> float:
    capital_gain = sale_price - cost_basis
    return capital_gain

def adjust_cost_basis_for_dividends(original_cost_basis: float, reinvested_dividends: list) -> float:
    adjusted_cost_basis = original_cost_basis + sum(reinvested_dividends)
    return adjusted_cost_basis

def calculate_futures_cost_basis(spot_price: float, futures_price: float) -> float:
    futures_cost_basis = futures_price - spot_price
    return futures_cost_basis

def estimate_opportunity_cost(benefit_of_chosen: float, benefit_of_next_best_alternative: float) -> float:
    opportunity_cost = benefit_of_next_best_alternative - benefit_of_chosen
    return opportunity_cost

def calculate_target_net_income(sales: float, fixed_costs: float, variable_costs: float) -> float:
    target_net_income = sales - fixed_costs - variable_costs
    return target_net_income

def calculate_cola_increase(previous_benefit: float, cola_percentage: float) -> float:
    new_benefit = previous_benefit * (1 + cola_percentage)
    return new_benefit

def calculate_cost_of_revenue(cogs: float, shipping_costs: float, commissions: float, warranties: float, returns: float, other_direct_costs: float) -> float:
    cost_of_revenue = cogs + shipping_costs + commissions + warranties + returns + other_direct_costs
    return cost_of_revenue

def calculate_breakeven_sales_volume(fixed_costs: float, contribution_margin_ratio: float) -> float:
    if not (0 < contribution_margin_ratio < 1):
        raise ValueError("Contribution margin ratio must be between 0 and 1.")
    breakeven_sales_volume = fixed_costs / contribution_margin_ratio
    return breakeven_sales_volume

def calculate_contribution_margin(total_sales: float, total_variable_costs: float) -> float:
    contribution_margin = total_sales - total_variable_costs
    return contribution_margin

def calculate_target_sales_volume(fixed_costs: float, contribution_margin_ratio: float, target_profit: float) -> float:
    if not (0 < contribution_margin_ratio < 1):
        raise ValueError("Contribution margin ratio must be between 0 and 1.")
    target_sales_volume = (fixed_costs + target_profit) / contribution_margin_ratio
    return target_sales_volume

def calculate_unit_contribution_margin(unit_sales_price: float, unit_variable_cost: float) -> float:
    unit_contribution_margin = unit_sales_price - unit_variable_cost
    return unit_contribution_margin

def calculate_interest_coverage_ratio(ebit: float, interest_expense: float) -> float:
    if interest_expense == 0:
        raise ValueError("Interest expense must be greater than 0.")
    interest_coverage_ratio = ebit / interest_expense
    return interest_coverage_ratio

def calculate_forward_exchange_rate(spot_rate: float, domestic_interest_rate: float, foreign_interest_rate: float) -> float:
    forward_rate = spot_rate * (1 + domestic_interest_rate) / (1 + foreign_interest_rate)
    return forward_rate

def calculate_credit_spread(corporate_bond_yield: float, treasury_bond_yield: float) -> float:
    credit_spread = corporate_bond_yield - treasury_bond_yield
    return credit_spread

def calculate_option_credit_spread(premium_received_high: float, premium_paid_low: float) -> float:
    net_credit = premium_received_high - premium_paid_low
    return net_credit

def calculate_bond_expected_loss(recovery_rate: float, default_probability: float) -> float:
    expected_loss = (1 - recovery_rate) * default_probability
    return expected_loss

def calculate_cup_and_handle_stop_loss(cup_bottom: float, handle_bottom: float, risk_tolerance: str = 'medium') -> float:
    if risk_tolerance == 'low':
        stop_loss = handle_bottom
    elif risk_tolerance == 'medium':
        stop_loss = (cup_bottom + handle_bottom) / 2
    elif risk_tolerance == 'high':
        stop_loss = cup_bottom
    else:
        raise ValueError("Invalid risk tolerance. Choose from 'low', 'medium', 'high'.")
    return stop_loss

def calculate_bid_ask_spread(bid_price: float, ask_price: float) -> float:
    if bid_price > ask_price:
        raise ValueError("Bid price should not be greater than ask price.")
    spread = ask_price - bid_price
    return spread

def calculate_vami(initial_investment: float, net_monthly_returns: list) -> list:
    vami_values = [initial_investment]
    for net_return in net_monthly_returns:
        next_vami = vami_values[-1] * (1 + net_return)
        vami_values.append(next_vami)

    return vami_values

def calculate_variance_covariance_var(mean_return: float, std_dev: float, z_score: float, portfolio_value: float) -> float:
    var_amount = portfolio_value * (mean_return - z_score * std_dev)
    return -var_amount

def calculate_value_averaging_contribution(target_growth: float, current_portfolio_value: float, target_portfolio_value: float, current_share_price: float) -> float:
    contribution = target_portfolio_value - current_portfolio_value
    return contribution

def calculate_price_to_book_ratio(market_price_per_share: float, book_value_per_share: float) -> float:
    if book_value_per_share <= 0:
        raise ValueError("Book value per share must be greater than zero.")
    pb_ratio = market_price_per_share / book_value_per_share
    return pb_ratio

def compare_to_industry(pe_ratio: float, industry_pe_ratio: float) -> str:
    if pe_ratio <= 0 or industry_pe_ratio <= 0:
        raise ValueError("P/E ratios must be positive numbers.")
    if pe_ratio < industry_pe_ratio:
        comparison = "The stock may be undervalued compared to the industry average."
    elif pe_ratio > industry_pe_ratio:
        comparison = "The stock may be overvalued compared to the industry average."
    else:
        comparison = "The stock is fairly valued compared to the industry average."
    return comparison

def calculate_option_cost(premium_per_share: float, number_of_shares: int) -> float:
    total_cost = premium_per_share * number_of_shares
    return total_cost

def calculate_option_profit_loss(stock_price_at_expiry: float, strike_price: float, premium: float, number_of_shares: int, is_call_option: bool) -> float:
    if is_call_option:
        intrinsic_value = max(0, stock_price_at_expiry - strike_price) * number_of_shares
    else:
        intrinsic_value = max(0, strike_price - stock_price_at_expiry) * number_of_shares
    total_cost = premium * number_of_shares
    profit_loss = intrinsic_value - total_cost
    return profit_loss

def calculate_variable_cost_plus_price(variable_costs: float, fixed_costs_per_unit: float, desired_profit_per_unit: float) -> float:
    selling_price = variable_costs + fixed_costs_per_unit + desired_profit_per_unit
    return selling_price

def calculate_adjusted_interest_rate(base_rate: float, margin: float) -> float:
    adjusted_rate = base_rate + margin
    return adjusted_rate

def calculate_effective_annual_rate(nominal_rate: float, compounding_periods: int) -> float:
    effective_rate = (1 + nominal_rate / compounding_periods) ** compounding_periods - 1
    return effective_rate

def calculate_variable_overhead_per_unit(total_variable_overhead: float, production_units: int) -> float:
    if production_units <= 0:
        raise ValueError("Production units must be greater than zero.")
    unit_cost = total_variable_overhead / production_units
    return unit_cost

def determine_rate_on_variable_cd(base_rate: float, adjustment_factor: float) -> float:
    cd_rate = base_rate - adjustment_factor
    return cd_rate

def calculate_fully_indexed_rate(indexed_rate: float, arm_margin: float) -> float:
    fully_indexed_rate = indexed_rate + arm_margin
    return fully_indexed_rate

def calculate_variance_swap_payout(actual_variance: float, strike_variance: float, notional: float) -> float:
    payout = notional * (actual_variance - strike_variance)
    return payout

def vasicek_interest_rate_change(a: float, b: float, r_t: float, sigma: float, dW_t: float, dt: float) -> float:
    dr_t = a * (b - r_t) * dt + sigma * dW_t
    return dr_t

def calculate_portfolio_vega(long_positions: list, short_positions: list) -> float:
    total_vega = sum(lots * vega for lots, vega in long_positions) - sum(lots * vega for lots, vega in short_positions)
    return total_vega

def calculate_vertical_analysis(line_items: dict, base_figure: float) -> dict:
    if base_figure == 0:
        raise ValueError("Base figure must not be zero.")
    vertical_analysis = {item: (amount / base_figure) * 100 for item, amount in line_items.items()}
    return vertical_analysis

def calculate_bear_call_spread_pnl(strike_price_short: float, strike_price_long: float, net_premium_received: float) -> dict:
    max_profit = net_premium_received
    max_loss = strike_price_long - strike_price_short - net_premium_received
    breakeven_point = strike_price_short + net_premium_received
    return {'max_profit': max_profit, 'max_loss': max_loss, 'breakeven_point': breakeven_point}

def calculate_bull_put_spread_pnl(strike_price_short: float, strike_price_long: float, net_premium_received: float) -> dict:
    max_profit = net_premium_received
    max_loss = strike_price_long - strike_price_short - net_premium_received
    breakeven_point = strike_price_short - net_premium_received
    return {
        'max_profit': max_profit,
        'max_loss': max_loss,
        'breakeven_point': breakeven_point
    }

def calculate_occupied_value(market_value: float, age: int, age_reduction_factor: float) -> float:
    occupied_value = market_value * (1 - (age * age_reduction_factor))
    return occupied_value

def calculate_annualized_volatility(standard_deviation: float, periods: int) -> float:
    if standard_deviation < 0:
        raise ValueError("Standard deviation must be non-negative.")
    if periods <= 0:
        raise ValueError("Periods must be a positive integer.")

    return standard_deviation * (periods ** 0.5)

def calculate_volatility_swap_payoff(notional_value: float, realized_volatility: float, volatility_strike: float) -> float:
    payoff = notional_value * (realized_volatility - volatility_strike)
    return payoff

def calculate_leading_span_a(conversion_line: float, base_line: float) -> float:
    leading_span_a = (conversion_line + base_line) / 2
    return leading_span_a

def calculate_senkou_span_a(tenkan_sen: float, kijun_sen: float) -> float:
    senkou_span_a = (tenkan_sen + kijun_sen) / 2
    return senkou_span_a

def calculate_recoverable_value(fair_value_less_costs_to_sell: float, value_in_use: float) -> float:
    recoverable_value = max(fair_value_less_costs_to_sell, value_in_use)
    return recoverable_value

def calculate_implied_rate(spot_price: float, forward_price: float, contract_time: float) -> float:
    if spot_price <= 0 or forward_price <= 0:
        raise ValueError("Spot and forward prices must be positive numbers.")
    if contract_time <= 0:
        raise ValueError("Contract time must be greater than zero.")

    implied_rate = (forward_price / spot_price) ** (1 / contract_time) - 1

    return implied_rate

def black_scholes_price(volatility):
        d1 = (math.log(stock_price / strike_price) + 
              (risk_free_rate + 0.5 * volatility ** 2) * time_to_expiration) / (volatility * math.sqrt(time_to_expiration))
        d2 = d1 - volatility * math.sqrt(time_to_expiration)

        if is_call:
            price = (stock_price * norm.cdf(d1) - strike_price * math.exp(-risk_free_rate * time_to_expiration) * norm.cdf(d2))
        else:
            price = (strike_price * math.exp(-risk_free_rate * time_to_expiration) * norm.cdf(-d2) - stock_price * norm.cdf(-d1))

        return price

def vega(volatility):
        d1 = (math.log(stock_price / strike_price) + 
              (risk_free_rate + 0.5 * volatility ** 2) * time_to_expiration) / (volatility * math.sqrt(time_to_expiration))
        return stock_price * norm.pdf(d1) * math.sqrt(time_to_expiration)

volatility = initial_vol_guess
    for _ in range(max_iterations):
        price = black_scholes_price(volatility)
        diff = option_price - price

        if abs(diff) < tolerance:
            return volatility

        vol_vega = vega(volatility)
        if vol_vega == 0:
            break

        volatility += diff / vol_vega

def calculate_intrinsic_value(option_type: str, stock_price: float, strike_price: float) -> float:
    if option_type.lower() == 'call':
        intrinsic_value = max(0, stock_price - strike_price)
    elif option_type.lower() == 'put':
        intrinsic_value = max(0, strike_price - stock_price)
    else:
        raise ValueError("Invalid option type. Available types are 'call' and 'put'.")
    return intrinsic_value

def calculate_bargain_element(strike_price: float, market_price: float) -> float:
    if strike_price < 0 or market_price < 0:
        raise ValueError("Prices must be non-negative.")
    bargain_element = market_price - strike_price
    return bargain_element

def calculate_incidence_rate(new_cases: int, population_at_risk: int, time_period: int = 1) -> float:
    if population_at_risk <= 0:
        raise ValueError("Population at risk must be greater than zero.")
    incidence_rate = (new_cases / population_at_risk) / time_period
    return incidence_rate

def calculate_income_from_operations(revenue: float, cost_of_goods_sold: float, operating_expenses: float) -> float:
    if revenue < 0 or cost_of_goods_sold < 0 or operating_expenses < 0:
        raise ValueError("Parameters must be non-negative.")
    income_from_operations = revenue - cost_of_goods_sold - operating_expenses
    return income_from_operations

def is_income_stock(volatility: float, dividend_yield: float, t_note_rate: float, profit_growth: float) -> bool:
    if volatility < 1 and dividend_yield > t_note_rate and profit_growth >= 0:
        return True
    return False

def calculate_incremental_profit(selling_price: float, labor_cost: float, material_cost: float, 
                                 overhead_cost: float, special_order_price: float, 
                                 fixed_cost: float, excess_capacity: bool) -> float:
    if excess_capacity:
        relevant_cost = labor_cost + material_cost + overhead_cost
    else:
        relevant_cost = labor_cost + material_cost + overhead_cost + fixed_cost

    incremental_profit = special_order_price - relevant_cost
    return incremental_profit

def calculate_incremental_cash_flow(revenues: float, expenses: float, initial_cost: float) -> float:
    incremental_cash_flow = revenues - expenses - initial_cost
    return incremental_cash_flow

def calculate_incremental_cost(total_cost_initial: float, total_cost_new: float, new_units_produced: int) -> float:
    if new_units_produced <= 0:
        raise ValueError("The number of new units produced must be greater than zero.")
    incremental_cost_total = total_cost_new - total_cost_initial
    incremental_cost_per_unit = incremental_cost_total / new_units_produced
    return incremental_cost_per_unit

def calculate_index_relative_change(current_index_value: float, base_index_value: float) -> float:
    if base_index_value == 0:
        raise ValueError("Base index value must be non-zero.")
    relative_change = current_index_value / base_index_value
    return relative_change

