def calculate_roth_ira_contribution(magi: float, filing_status: str, year: int) -> float:
    """
    Calculate the allowable Roth IRA contribution based on MAGI, filing status, and tax year.

    Args:
        magi (float): Modified Adjusted Gross Income.
        filing_status (str): Tax filing status ('single', 'married_jointly', 'married_separately').
        year (int): Tax year for which the contribution is calculated.

    Returns:
        contribution (float): The allowable contribution amount to a Roth IRA.

    Notes:
        - Applicability: Use this function for determining Roth IRA contributions under U.S. tax laws.
        - Constraints: Only applicable for years 2024 and 2025 with specific filing statuses.
        - Considerations: The contribution limits are subject to change; verify before use.
    """
    roth_limits = {
        2024: {
            'single': (146000, 161000),
            'married_jointly': (230000, 240000),
            'married_separately': (0, 10000)
        },
        2025: {
            'single': (150000, 165000),
            'married_jointly': (236000, 246000),
            'married_separately': (0, 10000)
        }
    }

    contribution_limits = {2024: 7000, 2025: 7000}

    phase_out_start, phase_out_end = roth_limits[year][filing_status]

    if magi < phase_out_start:
        return contribution_limits[year]
    elif magi >= phase_out_end:
        return 0
    else:
        range_span = phase_out_end - phase_out_start
        contribution_rate = (phase_out_end - magi) / range_span
        reduced_contribution = contribution_rate * contribution_limits[year]
        return max(0, min(reduced_contribution, contribution_limits[year]))

