def calculate_intrinsic_value(eps: float, growth_rate: float, bond_yield: float) -> float:
    intrinsic_value = (eps * (8.5 + 2 * growth_rate) * 4.4) / bond_yield
    return intrinsic_value

def calculate_yield_to_maturity(face_value: float, market_price: float, coupon_rate: float, years_to_maturity: int) -> float:
    def bond_price_at_rate(rate: float) -> float:
        return sum((coupon_rate * face_value) / ((1 + rate) ** t) for t in range(1, years_to_maturity + 1)) + face_value / ((1 + rate) ** years_to_maturity)
    lower_bound, upper_bound = 0.0, 1.0
    ytm = (lower_bound + upper_bound) / 2
    for _ in range(100):
        price = bond_price_at_rate(ytm)
        if abs(price - market_price) < 1e-5:
            return ytm
        elif price < market_price:
            lower_bound = ytm
        else:
            upper_bound = ytm
        ytm = (lower_bound + upper_bound) / 2
    return ytm

def calculate_bond_discount(par_value: float, market_price: float) -> float:
    discount = par_value - market_price
    return discount

def calculate_bond_discount_rate(par_value: float, market_price: float) -> float:
    discount_rate = (par_value - market_price) / par_value
    return discount_rate

def calculate_bond_futures_price(futures_price: float, conversion_factor: float, accrued_interest: float) -> float:
    price = (futures_price * conversion_factor) + accrued_interest
    return price

def calculate_bond_dollar_price(quote_percent: float, face_value: float) -> float:
    dollar_price = (quote_percent / 100) * face_value
    return dollar_price

def calculate_annual_yield(coupon_rate: float, market_price: float, face_value: float) -> float:
    annual_yield = (coupon_rate * face_value) / market_price * 100
    return annual_yield

def calculate_adjusted_share_price(original_price: float, bonus_ratio: float) -> float:
    if bonus_ratio <= 0:
        raise ValueError("Bonus ratio must be a positive number.")
    adjusted_price = original_price / (1 + bonus_ratio)
    return adjusted_price

def calculate_book_to_market_ratio(book_value: float, market_cap: float) -> float:
    if market_cap <= 0:
        raise ValueError("Market capitalization must be greater than zero.")
    book_to_market_ratio = book_value / market_cap
    return book_to_market_ratio

def calculate_bottom_line(total_revenue: float, total_expenses: float) -> float:
    net_income = total_revenue - total_expenses
    return net_income

def calculate_box_spread_max_loss(net_premium_paid: float, commissions: float) -> float:
    max_loss = net_premium_paid + commissions
    return max_loss

def calculate_break_even_price_fixed_variable(fixed_cost: float, variable_cost_per_unit: float, unit_price: float) -> float:
    if unit_price <= variable_cost_per_unit:
        raise ValueError("Unit price must be greater than variable cost per unit to calculate break-even.")
    break_even_units = fixed_cost / (unit_price - variable_cost_per_unit)
    return break_even_units

def calculate_contribution_margin(unit_price: float, variable_cost_per_unit: float) -> float:
    contribution_margin = unit_price - variable_cost_per_unit
    return contribution_margin

def calculate_breakeven_revenue(fixed_costs: float, gross_profit_margin: float) -> float:
    if gross_profit_margin <= 0:
        raise ValueError("Gross profit margin must be greater than 0 for breakeven analysis.")
    breakeven_revenue = fixed_costs / gross_profit_margin
    return breakeven_revenue

def calculate_budget_surplus(income: float, expenditures: float) -> float:
    surplus = income - expenditures
    return surplus

def calculate_budget_variance(budgeted_amount: float, actual_amount: float) -> float:
    variance = actual_amount - budgeted_amount
    return variance

def calculate_bull_put_spread_profit_loss(sell_premium: float, buy_premium: float, sell_strike: float, buy_strike: float, stock_price_at_expiry: float) -> dict:
    net_credit = sell_premium - buy_premium
    max_profit = net_credit
    max_loss = (sell_strike - buy_strike) - net_credit
    if stock_price_at_expiry > sell_strike:
        profit_loss = max_profit
    elif stock_price_at_expiry < buy_strike:
        profit_loss = -max_loss
    else:
        profit_loss = net_credit - (sell_strike - stock_price_at_expiry)
    return {'max_profit': max_profit, 'max_loss': max_loss, 'profit_loss': profit_loss}

def calculate_bull_call_spread_profit(lower_strike: float, higher_strike: float, net_premium_paid: float) -> float:
    max_profit = (higher_strike - lower_strike) - net_premium_paid
    return max_profit

def calculate_bull_put_spread_profit(higher_strike: float, lower_strike: float, net_credit_received: float) -> float:
    max_profit = net_credit_received
    return max_profit

def calculate_bull_call_spread_breakeven(lower_strike: float, net_premium_paid: float) -> float:
    breakeven = lower_strike + net_premium_paid
    return breakeven

def calculate_bull_put_spread_breakeven(higher_strike: float, net_credit_received: float) -> float:
    breakeven = higher_strike - net_credit_received
    return breakeven

def calculate_present_value_bullet_bond(payments: list, bond_yield: float, periods: list) -> float:
    present_value = sum(payment / (1 + (bond_yield / 2)) ** period for payment, period in zip(payments, periods))
    return present_value

def calculate_burn_rate(total_expenses: float, monthly_revenue: float = 0.0, cost_of_goods_sold: float = 0.0) -> float:
    if monthly_revenue > 0 or cost_of_goods_sold > 0:
        burn_rate = (monthly_revenue - cost_of_goods_sold) - total_expenses
    else:
        burn_rate = total_expenses
    return burn_rate

def calculate_market_capitalization(share_price: float, total_shares_outstanding: int) -> float:
    market_cap = share_price * total_shares_outstanding
    return market_cap

def calculate_book_value(total_assets: float, total_liabilities: float) -> float:
    book_value = total_assets - total_liabilities
    return book_value

def calculate_times_revenue_valuation(revenue: float, industry_multiplier: float) -> float:
    valuation = revenue * industry_multiplier
    return valuation

if is_long_call:
    if underlying_price == middle_strike:
        return middle_strike - lower_strike - premium_cost
    else:
        return -premium_cost

else:
    if underlying_price <= lower_strike or underlying_price >= upper_strike:
        return premium_cost
    else:
        return lower_strike - upper_strike + premium_cost

def calculate_short_sale_profit(short_sale_price: float, buy_to_cover_price: float, shares_sold: int) -> float:
    profit = (short_sale_price - buy_to_cover_price) * shares_sold
    return profit

def calculate_new_eps(current_eps: float, shares_repurchase_percentage: float) -> float:
    if not (0 <= shares_repurchase_percentage < 1):
        raise ValueError("Shares repurchase percentage must be between 0 and 1.")
    new_eps = current_eps / (1 - shares_repurchase_percentage)
    return new_eps

def calculate_maintenance_margin_call_threshold(deposit: float, maintenance_margin_rate: float) -> float:
    threshold = deposit * maintenance_margin_rate
    return threshold

def calculate_margin_buying_power(cash_balance: float, initial_margin_requirement: float) -> float:
    if not (0 < initial_margin_requirement <= 1):
        raise ValueError("Initial margin requirement must be between 0 and 1.")
    buying_power = cash_balance / initial_margin_requirement
    return buying_power

def calculate_return_on_capital(ebit: float, net_fixed_assets: float, working_capital: float) -> float:
    capital = net_fixed_assets + working_capital
    if capital == 0:
        raise ValueError("Sum of net fixed assets and working capital must not be zero.")
    return_on_capital = ebit / capital
    return return_on_capital

def calculate_maintenance_margin(securities_value: float, margin_requirement: float = 0.25) -> float:
    if securities_value < 0:
        raise ValueError("Securities value must be non-negative.")
    if not (0 <= margin_requirement <= 1):
        raise ValueError("Margin requirement must be between 0 and 1.")
    maintenance_margin = securities_value * margin_requirement
    return maintenance_margin

def calculate_initial_margin(purchase_price: float, margin_requirement: float) -> float:
    if not (0 <= margin_requirement <= 1):
        raise ValueError("Margin requirement must be between 0 and 1.")
    initial_margin = purchase_price * margin_requirement
    return initial_margin

def calculate_adjustable_rate_mortgage_interest(index_rate: float, margin: float) -> float:
    arm_interest_rate = index_rate + margin
    return arm_interest_rate

def calculate_maintenance_margin_equity(security_value: float, maintenance_margin_requirement: float) -> float:
    required_equity = security_value * maintenance_margin_requirement
    return required_equity

def calculate_margin_call(security_value: float, current_equity: float, maintenance_margin_requirement: float) -> float:
    required_equity = security_value * maintenance_margin_requirement
    if current_equity < required_equity:
        margin_call_amount = required_equity - current_equity
    else:
        margin_call_amount = 0.0
    return margin_call_amount

def calculate_margin_call_equity(security_value: float, loan_amount: float) -> float:
    equity = security_value - loan_amount
    return equity

def calculate_maintenance_requirement(security_value: float, maintenance_margin: float) -> float:
    maintenance_requirement = security_value * maintenance_margin
    return maintenance_requirement

def calculate_additional_funds_needed(equity: float, maintenance_requirement: float) -> float:
    additional_funds = max(0.0, maintenance_requirement - equity)
    return additional_funds

def calculate_total_deposit_for_margin_call(required_funds: float, equity_requirement: float) -> float:
    total_deposit = required_funds / (1 - equity_requirement)
    return total_deposit

def calculate_margin_call_equity(stock_value: float, margin_debt: float, maintenance_margin: float) -> float:
    min_equity = stock_value * maintenance_margin
    return min_equity

def calculate_marginal_benefit(marginal_benefits: list, prices: list) -> int:
    for i, (benefit, price) in enumerate(zip(marginal_benefits, prices)):
        if benefit < price:
            return i
    return len(marginal_benefits)

def calculate_marginal_profit(marginal_revenue: float, marginal_cost: float) -> float:
    marginal_profit = marginal_revenue - marginal_cost
    return marginal_profit

def calculate_marginal_propensity_to_consume(change_in_consumption: float, change_in_income: float) -> float:
    if change_in_income == 0:
        raise ValueError("Change in income must be non-zero to calculate MPC.")
    mpc = change_in_consumption / change_in_income
    return mpc

def calculate_marginal_rate_of_transformation(mc_x: float, mc_y: float) -> float:
    if mc_y == 0:
        raise ValueError("The marginal cost of good Y (mc_y) must be non-zero and positive.")
    mrt = mc_x / mc_y
    return mrt

def calculate_marginal_revenue_product(marginal_physical_product: float, marginal_revenue: float) -> float:
    marginal_revenue_product = marginal_physical_product * marginal_revenue
    return marginal_revenue_product

def calculate_marginal_social_cost(marginal_private_cost: float, marginal_external_cost: float) -> float:
    marginal_social_cost = marginal_private_cost + marginal_external_cost
    return marginal_social_cost

def calculate_advance_decline_index(advancing_stocks: int, declining_stocks: int) -> int:
    ad_index = advancing_stocks - declining_stocks
    return ad_index

def calculate_new_highs_lows_ratio(new_highs: int, new_lows: int) -> float:
    if new_lows == 0:
        raise ValueError("The number of new lows must be greater than 0 to avoid division by zero.")
    ratio = new_highs / new_lows
    return ratio

def calculate_bid_ask_spread(bid_price: float, ask_price: float) -> float:
    if ask_price < bid_price:
        raise ValueError("Ask price must be greater than or equal to bid price.")
    spread = ask_price - bid_price
    return spread

def calculate_married_put_breakeven(stock_price: float, option_premium: float) -> float:
    breakeven_price = stock_price + option_premium
    return breakeven_price

def calculate_gas_guzzler_tax(mpg: float) -> int:
    """
    Calculate the gas guzzler tax based on a vehicle's fuel efficiency.

    This function determines the amount of gas guzzler tax imposed on a passenger
    car based on its miles-per-gallon (mpg) fuel economy. The tax is part of a 
    U.S. government initiative to discourage low fuel economy vehicles.

    Args:
        mpg (float): The combined city and highway miles-per-gallon fuel efficiency
                     of the car.

    Returns:
        tax_amount (int): The calculated gas guzzler tax in dollars.

    Notes:
        - Applicability: This tax is applicable to passenger cars but not to 
          trucks, SUVs, or minivans.
        - Constraints: The function uses pre-defined tax brackets based on mpg 
          efficiency, ranging from $1,000 to $7,000.
        - Considerations: Tax brackets are defined for mpg values thresholds such as
          less than 12.5 mpg, less than 22.5 mpg, etc. Updates to the tax code could 
          change these brackets.
    """
    if mpg >= 22.5:
        return 0
    elif mpg < 12.5:
        return 7000
    elif mpg < 13.5:
        return 6400
    elif mpg < 14.5:
        return 5800
    elif mpg < 15.5:
        return 5000
    elif mpg < 16.5:
        return 4500
    elif mpg < 17.5:
        return 3800
    elif mpg < 18.5:
        return 3000
    elif mpg < 19.5:
        return 2600
    elif mpg < 20.5:
        return 2100
    elif mpg < 21.5:
        return 1600
    elif mpg < 22.5:
        return 1000
    else:
        return 0

